public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int maxArea = 0;
    Stack<Integer> stack = new Stack<>();

    for (int i = 0; i <= n; ) {
        int currentHeight = (i < n) ? heights[i] : 0;

        if (stack.isEmpty() || currentHeight >= heights[stack.peek()]) {
            stack.push(i++);
        } else {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            maxArea = Math.max(maxArea, height * width);
        }
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int index = 0;

    boolean up = true;
    for (int i = 0; i < rows + cols - 1; i++) {
        if (up) {
            int row = Math.min(i, rows - 1);
            int col = i - row;
            while (row >= 0 && col < cols) {
                result[index++] = mat[row][col];
                row--;
                col++;
            }
            up = false;
        } else {
            int col = Math.min(i, cols - 1);
            int row = i - col;
            while (col >= 0 && row < rows) {
                result[index++] = mat[row][col];
                row++;
                col--;
            }
            up = true;
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1;
    }
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    j = digits.length - 1;
    while (i < j) {
        temp = digits[i];
        digits[i] = digits[j];
        digits[j] = temp;
        i++;
        j--;
    }
    return Integer.parseInt(new String(digits));
}

